actions.script:
if (ec.user.userId && !ec.user.isInGroup('ADMIN')) throw new Error('Demo loading requires system administration')
// the server's local day, as the demo data's fixed dates are read
const now = new Date(ec.user.timestampMillis(ec.user.nowTimestamp))
const after = (days) => String(new Date(now.getFullYear(), now.getMonth(), now.getDate() + days).getTime())
const move = (orderId, validThruDate) => {
    const keys = {orderId, orderPartSeqId: '01'}
    if (ec.entity.find('mantle.order.OrderPart').condition(keys).disableAuthz().one() == null) {
        ec.logger.warn('The quote dates demo found no quote ' + orderId + '; not moved')
        return
    }
    ec.service.sync().name('update#mantle.order.OrderPart').parameters(Object.assign({validThruDate}, keys)).disableAuthz().call()
}
// as the loaded row: no order part change rule, which would count a new revision of the quote (its specs act on revision 1)
const wasDisabled = ec.artifactExecution.disableEntityEca()
try {
    wingtipThruDate = after(77)
    move('BOSS_SAL_QTE_WINGTIP', wingtipThruDate)
    move('BOSS_SAL_QTE_FABRIKAM', after(105))
} finally {
    if (!wasDisabled) ec.artifactExecution.enableEntityEca()
}
